SELECT

FROM blog_post p
LEFT JOIN blog_category c ON c.category_id = p.category_id

    p.del_flag = '0'

        AND p.title LIKE CONCAT('%', #{title}, '%')


        AND p.category_id = #{categoryId}


        AND p.status = #{status}


ORDER BY p.is_top DESC, p.published_time DESC, p.post_id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM blog_post p

    p.del_flag = '0'

        AND p.title LIKE CONCAT('%', #{title}, '%')


        AND p.category_id = #{categoryId}


        AND p.status = #{status}

